a:relatedActionCfg.a:visibilityExpr:
a!localVariables(
  local!userBU: a!refreshVariable(
    value: union(
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      ),
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      )
    ),
    refreshAlways: true
  ),
  local!ismemberofusergroup: or(
    contains(
      touniformstring(local!userBU),
      tostring(
        rv!record[#"urn:appian:record-field:v1:3c9090dc-94e8-40f2-b0c1-5161f315f66c/originatingBU"]
      )
    ),
    contains(
      touniformstring(local!userBU),
      tostring(
        rv!record[#"urn:appian:record-field:v1:3c9090dc-94e8-40f2-b0c1-5161f315f66c/returnBU"]
      )
    ),
    a!isNullOrEmpty(local!userBU)
  ),
  and(
    #"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
      username: loggedInUser(),
      groups: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
    ),
    rv!record[#"urn:appian:record-field:v1:3c9090dc-94e8-40f2-b0c1-5161f315f66c/nominationStatus"] <> #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3888843",
    local!ismemberofusergroup
  )
)

